function rows(s){if(lists[s.id])return lists[s.id];return (s.ui.rows||[]).map(r=>r.map(v=>String(v).replaceAll('—','미등록').replaceAll('국가 ','국가 미등록').replaceAll('기간 협의','기간 미등록').replaceAll('시간 ','14:00').replaceAll('시각 ','2026-10-02 14:00').replaceAll('단위 협의','금액 미등록').replaceAll('원통화별','USD').replaceAll('환산 기준 필요','환산 미적용').replaceAll('분모 표시','기준 미등록').replaceAll('분모 확인','기준 미등록').replaceAll('척도 협의','미집계')))}
function filterOpts(t,s){if(s?.id==='BAS-01'&&t==='연도')return ['전체',...Array.from({length:20},(_,i)=>String(2026-i))];if(s?.id==='BAS-01'&&t==='상태')return ['전체','대기','진행','종료'];if(s?.id==='BAS-01'&&t==='행사명')return null;if(['BAS-03','BAS-05','BAS-07'].includes(s?.id)&&t==='참가연도'){const idx=s.id==='BAS-03'?4:3,years=[...new Set(rows(s).flatMap(r=>String(r[idx]||'').match(/20\d{2}/g)||[]))].sort((a,b)=>Number(b)-Number(a));return ['전체',...years]}if(['BAS-03','BAS-05','BAS-07'].includes(s?.id)&&t==='참가 상태')return ['전체','신규','참가 확정','참가 미정'];if(t==='이동상태')return ['전체',...travelStages];if(t==='운영 상태')return ['전체','행사전','행사중','종료'];if(t==='검수 상태')return ['전체','대기','승인','반려'];if(/상태|승인|여부/.test(t))return ['전체','준비','운영','종료','승인','대기','반려','출석','미출석'];if(/유형|구매.*수출|상담 구분/.test(t))return ['전체','구매','수출'];if(/역할|국내.*해외.*통역|참가자/.test(t))return ['전체','국내바이어','해외바이어','통역원'];if(/연도/.test(t))return ['전체','2026','2025'];if(/행사/.test(t))return ['전체','G-FAIR KOREA 2026','G-FAIR KOREA 2025'];return null}
function filters(s){if(s.id==='BAS-01')return `<form id="filter-form" class="panel filters">${F('상태',`<select name="f0">${O(['전체','대기','진행','종료'],filter.f0||'전체')}</select>`)}${F('키워드검색',I('f2','search',filter.f2||'','aria-label="키워드검색"'))}<div class="row"><button type="submit" class="btn primary">검색</button>${B('reset','초기화')}</div></form>`;return `<form id="filter-form" class="panel filters">${(s.ui.filters||[]).map((t,i)=>{const opts=filterOpts(t,s),placeholder=s.id==='BAS-01'&&t==='행사명'?'행사명을 입력하세요.':`${t} 입력`;return F(t,opts?`<select name="f${i}">${O(opts,filter['f'+i]||'전체')}</select>`:I('f'+i,/일자|날짜/.test(t)?'date':'search',filter['f'+i]||'',`placeholder="${E(placeholder)}"`))}).join('')}<div class="row"><button type="submit" class="btn primary">검색</button>${B('reset','초기화')}</div></form>`}
function filtered(s){if(s.id==='BAS-01'){const query=String(filter.f2||'').trim().toLowerCase(),scope=window.GFAIR_SEARCH_SCOPE?.('f2')||'전체';return rows(s).map((r,i)=>({r,i})).filter(({r})=>{const halls=r[0]==='2026'?'생활용품(반려동물) 생활용품(주방용품) 생활용품(생활용품) 생활용품(인테리어) 생활용품(헬스케어) 식품 뷰티/패션 테크':'생활용품 식품 뷰티/패션 테크',text=scope==='행사명'?r[1]:scope==='전시관구분'?halls:r[1]+' '+halls;return (!filter.f0||filter.f0==='전체'||r[3]===filter.f0)&&(!query||text.toLowerCase().includes(query))})}return rows(s).map((r,i)=>({r,i})).filter(({r})=>Object.entries(filter).filter(([,t])=>t&&t!=='전체'&&!t.startsWith('G-FAIR')).every(([key,t])=>{const label=s.ui.filters?.[Number(key.slice(1))];const searchScope=window.GFAIR_SEARCH_SCOPE?.(key)||'전체';if(searchScope!=='전체'){const col=s.ui.columns?.findIndex(c=>c===searchScope);if(col>=0)return String(r[col]).toLowerCase().includes(t.trim().toLowerCase());}if(['BAS-03','BAS-05','BAS-07'].includes(s.id)){const yearIndex=s.id==='BAS-03'?4:3;if(label==='참가연도')return String(r[yearIndex]||'').split(/[,，]\s*/).includes(t);if(label==='참가 상태')return r[r.length-1]===t;}if(s.id==='BAS-01'){if(label==='연도')return r[0]===t;if(label==='상태')return r[3]===t;if(label==='행사명')return r[1].toLowerCase().includes(t.trim().toLowerCase())}if(s.id==='BAS-01'&&label==='운영 상태'){const status=({준비:'행사전',운영:'행사중',행사전:'행사전',행사중:'행사중',종료:'종료'})[r[3]]||r[3];return status===t}if(['BAS-05','EVT-01'].includes(s.id)){if(['바이어명·고유 번호','바이어명 · 고유번호'].includes(label))return [r[0],r[1]].some(v=>String(v).includes(t.trim()));if(label==='소속 기업')return String(r[2]).includes(t.trim());if(label==='검수 상태')return r[3]===t;}return r.join(' ').includes(t)}))}
