function dashboardStack(labels,values,colors){const total=values.reduce((a,b)=>a+b,0);return `<ul class="overview-legend">${labels.map((t,i)=>`<li><i style="background:${colors[i]}"></i><span>${E(t)}</span><b>${values[i]}명</b></li>`).join('')}</ul><div class="overview-stack" role="img" aria-label="${E(labels.map((t,i)=>t+' '+values[i]+'명').join(', '))}">${values.map((v,i)=>`<span style="width:${total?v/total*100:0}%;background:${colors[i]}">${Math.round(total?v/total*100:0)}%</span>`).join('')}</div>`}
function dashboardPending(type){const rr=jRows({id:'JNL-01'}).filter(j=>j.type===type&&j.status==='승인 요청');return `<section class="overview-pending"><div class="overview-section-head"><h3>승인 요청 ${type}상담일지 <span>/ ${rr.length}건</span></h3>${A(type==='구매'?'JNL-13':'JNL-14','전체 보기','btn ghost')}</div><div class="tablewrap"><table><thead><tr><th>기업명</th>${type==='수출'?'<th>해외바이어</th>':''}<th>상담액</th><th>계약 추진액</th><th>상담일시</th><th>작성자</th><th>상태</th><th>상세</th></tr></thead><tbody>${rr.length?rr.map(j=>`<tr><td>${E(j.company)}</td>${type==='수출'?`<td>${E(j.buyer)}</td>`:''}<td>${Number(j.amount).toLocaleString()} <small>${E(j.currency)}</small></td><td>${Number(j.contract).toLocaleString()} <small>${E(j.currency)}</small></td><td>${E(j.time)}</td><td>${E(j.writer)}</td><td>${badge('승인 요청')}</td><td>${B('j-detail','조회','btn ghost',`data-id="${E(j.id)}"`)}</td></tr>`).join(''):`<tr><td colspan="${type==='수출'?8:7}">승인 요청 상담일지가 없습니다.</td></tr>`}</tbody></table></div></section>`}
function dashboardArea(type){const buy=type==='구매',d=dashboardExample[buy?'buy':'export'],colors=['#919191','#a9a9a9','#949494','#bebebe'],itemLabels=['식품','주방','레저','미용','패션','테크','인테리어','전자기기','기타'];return `<section class="overview-area" aria-label="${type}상담 대시보드"><h2><i></i>${type}상담 대시보드</h2><div class="overview-two">${dashTile('출석 예정 '+(buy?'국내':'해외')+' 바이어 수',d.expected)}${dashTile('상담 진행 중인 '+(buy?'국내 바이어':'통역원')+' 수',d.active)}</div><div class="overview-two"><article class="overview-chart"><h3>${buy?'국내':'해외'} 바이어 출결 현황</h3>${dashboardStack(['미출석','출석'],d.attendance,colors)}</article><article class="overview-chart"><div class="overview-section-head"><h3>${buy?'분류별 국내 바이어 수 통계':'해외 바이어 방한 정보'}</h3>${!buy?A('PRE-01','상세 보기','btn ghost'):''}</div>${buy?dashboardStack(['리빙','뷰티','식품','기타'],d.categories,colors):`<ul class="overview-travel">${d.travel.map(([t,v])=>`<li><span>${E(t)}</span><b>${v}명</b></li>`).join('')}</ul>`}</article></div><div class="overview-three">${dashTile((buy?'국내':'해외')+' 바이어 상담 건수',d.count,'건')}${dashTile((buy?'국내':'해외')+' 바이어 상담액',d.amount,d.amountUnit)}${dashTile(buy?'국내 바이어 계약 추진액':'수출상담 계약 추진액',d.contractAmount,d.contractUnit)}</div><div class="overview-two"><article class="overview-chart"><h3>${type}상담일지 현황</h3><div class="overview-status"><div class="overview-donut" style="background:conic-gradient(#a9a9a9 0 ${d.status[0]/d.count*100}%,#bebebe ${d.status[0]/d.count*100}% ${(d.status[0]+d.status[1])/d.count*100}%,#919191 0)" role="img" aria-label="승인 완료 ${d.status[0]}건, 승인 요청 ${d.status[1]}건, 반려 ${d.status[2]}건"><span>${d.count}<small>등록 건수</small></span></div><ul class="overview-legend status-legend">${['승인 완료','승인 요청','반려'].map((t,i)=>`<li><i style="background:${['#a9a9a9','#bebebe','#919191'][i]}"></i><span>${t}</span><b>${d.status[i]}건</b></li>`).join('')}</ul></div></article><article class="overview-chart"><div class="overview-section-head"><h3>품목별 상담 현황</h3><small>단위: 건</small></div><div class="overview-bars" role="img" aria-label="${E(itemLabels.map((t,i)=>t+' '+d.items[i]+'건').join(', '))}">${itemLabels.map((t,i)=>`<div><b>${d.items[i]}</b><span style="height:${d.items[i]}px"></span><small>${t}</small></div>`).join('')}</div></article></div>${dashboardPending(type)}<p class="overview-note">상담액과 계약 추진액은 원통화 기준</p></section>`}
dash=function(s){if(!['MON-01','MON-02','MON-03'].includes(s.id))return previousDashboard(s);const showBuy=s.id==='MON-02'||s.id==='MON-01'&&kind!=='수출',showExport=s.id==='MON-03'||s.id==='MON-01'&&kind!=='구매';const b=dashboardExample.buy,e=dashboardExample.export,total=(showBuy?b.count:0)+(showExport?e.count:0);return `${head(s,monitoringUpdateControl())}${s.id==='MON-01'?`<div class="toolbar"><div class="tabs">${['전체','구매','수출'].map(k=>B('kind',k,'btn '+(kind===k?'primary':''),`data-kind="${k}" aria-pressed="${kind===k}"`)).join('')}</div></div>`:''}<div class="kpis overview-kpis">${[['상담중인 부스',showBuy&&showExport?76:showBuy?32:44,'개','현재 상담 진행 중'],['상담일지 등록 건수',total,'건','구매·수출 등록 기준'],['총 상담액',showBuy&&showExport?'3.2억원 / 1.8백만 USD':showBuy?'3.2억원':'1.8백만 USD','','원통화별 합계'],['총 계약 추진 건수',(showBuy?b.contracts:0)+(showExport?e.contracts:0),'건','계약 추진 중'],['총 계약 추진액',showBuy&&showExport?'0.9억원 / 0.6백만 USD':showBuy?'0.9억원':'0.6백만 USD','','원통화별 합계']].map(([t,v,u,n])=>`<article class="kpi"><div class="kpi-label">${t}</div><div class="kpi-value ${typeof v==='string'?'overview-money':''}">${E(v)}<small>${u}</small></div><div class="kpi-note">${n}</div></article>`).join('')}</div><div class="overview-grid ${showBuy&&showExport?'':'overview-single'}">${showBuy?dashboardArea('구매'):''}${showExport?dashboardArea('수출'):''}</div>`};
