function travelOverview(s){const rr=rows(s),colors=['#6e6e6e','#888888','#787878','#7f7f7f','#858585','#a3a3a3'];return `<section class="panel travel-overview" aria-label="해외 바이어 단계별 방한 현황"><div class="travel-overview-head"><h2>해외 바이어 방한 현황</h2><span>전체 ${rr.length}명 · 현재 행사 </span></div><div class="travel-stage-grid"><article class="travel-stage travel-total" style="--stage-color:#333"><span class="travel-stage-name"><i data-lucide="users-round" aria-hidden="true"></i>총 해외 바이어</span><strong data-travel-total>${rr.length}<small>명</small></strong><span class="travel-stage-caption">현재 행사 전체 대상</span></article>${travelStages.map((stage,i)=>{const count=rr.filter(r=>r[4]===stage).length;return `<button type="button" class="travel-stage ${filter.f3===stage?'active':''}" data-action="travel-stage" data-stage="${E(stage)}" aria-pressed="${filter.f3===stage}" style="--stage-color:${colors[i]}"><span class="travel-stage-name"><i data-lucide="${['plane-landing','bus','hotel','map-pin','users','messages-square'][i]}" aria-hidden="true"></i>${E(stage)}</span><strong>${count}<small>명</small></strong><span class="travel-stage-caption">현재 단계</span></button>`}).join('')}</div><div class="travel-updated"><span>Last updated: <time datetime="${travelUpdated.toISOString()}">${E(travelUpdated.toLocaleString('ko-KR',{hour12:false}))}</time></span>${B('travel-refresh','새로고침','btn ghost')}</div></section>`}
