function matchingChips(selected){return selected.map(v=>`<button type="button" class="matching-chip" data-action="matching-remove" data-value="${E(v)}" aria-label="${E(v)} 선택 해제">${E(v)}<span aria-hidden="true">⊗</span></button>`).join('')}
function matchingMulti(label,key,options,placeholder='내용을 입력해주세요'){const selected=Array.isArray(filter[key])?filter[key]:[];return `<div class="field"><span>${E(label)}</span><details class="matching-multi" data-multi-filter><summary aria-label="${E(label)} 복수 선택">${E(label)}${selected.length?' ('+selected.length+')':''}<span aria-hidden="true">⌄</span></summary><div class="matching-options" role="group" aria-label="${E(label)}"><input type="search" class="matching-search" placeholder="${E(placeholder)}" aria-label="${E(label)} 항목 검색"><div class="matching-chips" aria-live="polite">${matchingChips(selected)}</div><div class="matching-option-grid">${options.map(v=>`<label data-option="${E(v)}"><input type="checkbox" name="${key}" value="${E(v)}" ${selected.includes(v)?'checked':''}><span>${E(v)}</span></label>`).join('')}</div><p class="matching-no-results" hidden>검색 결과가 없습니다.</p></div></details></div>`}
