let statisticsCategory='리빙';
function statisticsData(){const buy=kind!=='수출',exp=kind!=='구매',b=dashboardExample.buy,e=dashboardExample.export;return {buy,exp,count:(buy?b.count:0)+(exp?e.count:0),contracts:(buy?b.contracts:0)+(exp?e.contracts:0),attendance:[(buy?6:0)+(exp?12:0),(buy?42:0)+(exp?96:0)],companies:buy&&exp?[84,16]:buy?[42,8]:[64,12],buyers:[(buy?42:0)+(exp?96:0),(buy?6:0)+(exp?12:0)],money:buy&&exp?'3.2억원 / 1.8백만 USD':buy?'3.2억원':'1.8백만 USD',contractMoney:buy&&exp?'0.9억원 / 0.6백만 USD':buy?'0.9억원':'0.6백만 USD'}}
function statisticsRanks(group){const exportOnly=group==='해외 바이어'||kind==='수출',currency=exportOnly?'USD':'KRW',counts=group==='국내 바이어'?[48,40,32,28,20]:group==='해외 바이어'?[90,75,62,51,40]:group==='참가기업'?(kind==='전체'?[130,110,100,80,66]:kind==='구매'?[48,40,32,28,20]:[90,75,62,51,40]):[42,36,30,24,18];const names=group==='품목별'?{리빙:['주방용품','생활용품','인테리어','가구','청소용품'],뷰티:['스킨케어','색조 화장품','미용기기','헤어케어','네일용품'],식품:['가공식품','음료','건강식품','간편식','과자'],기타:['산업용품','전자기기','스포츠용품','문구','기타제품']}[statisticsCategory]:counts.map((_,i)=>''+group+' '+String.fromCharCode(65+i));return names.map((name,i)=>({name,count:counts[i],amount:counts[i]*(currency==='USD'?2000:1000000),currency,exportAmount:kind==='전체'&&group==='참가기업'?counts[i]*2000:null}))}
function statisticsRankSection(group,color){const rr=statisticsRanks(group),max=Math.max(...rr.map(r=>r.count));return `<section class="statistics-ranking"><div class="statistics-section-title"><h2><i></i>${E(group)} TOP5</h2>${group==='품목별'?`<label class="statistics-category"><span class="small">품목 분류</span><select id="statistics-category" aria-label="품목 분류">${O(['리빙','뷰티','식품','기타'],statisticsCategory)}</select></label>`:''}${A(group==='품목별'?'STA-04':'STA-03','상세 보기','btn ghost')}</div><div class="statistics-rank-body"><div><div class="statistics-chart-title"><h3>누적 상담 건수</h3><small>단위: 건</small></div><div class="statistics-horizontal">${rr.map(r=>`<div><span>${E(r.name)}</span><b>${r.count}건</b><div class="statistics-track"><span style="width:${r.count/max*100}%;background:${color}"></span></div></div>`).join('')}</div></div><div><div class="statistics-chart-title"><h3>누적 상담 금액</h3><small>원통화 기준</small></div><div class="tablewrap"><table><thead><tr><th>NO</th><th>${E(group)}</th><th>금액</th></tr></thead><tbody>${rr.map((r,i)=>`<tr><td>${i+1}</td><td>${E(r.name)}</td><td>${r.amount.toLocaleString()} ${r.currency}${r.exportAmount?`<small>${r.exportAmount.toLocaleString()} USD</small>`:''}</td></tr>`).join('')}</tbody></table></div></div></div></section>`}
function statisticsJournal(type){const d=dashboardExample[type==='구매'?'buy':'export'];return `<div class="statistics-journal"><h3>${type}상담일지</h3><div class="overview-status"><div class="overview-donut" style="background:conic-gradient(#949494 0 ${d.status[0]/d.count*100}%,#bebebe ${d.status[0]/d.count*100}% ${(d.status[0]+d.status[1])/d.count*100}%,#919191 0)" role="img" aria-label="${type} 승인 ${d.status[0]}건, 대기 ${d.status[1]}건, 반려 ${d.status[2]}건"><span>${type}<small>${d.count}건</small></span></div><ul class="overview-legend status-legend">${['승인 완료','승인 요청','반려'].map((t,i)=>`<li><i style="background:${['#949494','#bebebe','#919191'][i]}"></i><span>${t}</span><b>${d.status[i]}건</b></li>`).join('')}</ul></div></div>`}
const statisticsDashboard=dash;
dash=function(s){if(s.id!=='STA-01')return statisticsDashboard(s);const d=statisticsData(),progress=kind==='구매'?[20,16,14,10]:kind==='수출'?[30,24,22,18]:[50,40,36,28];return `${head({...s,title:'통계 대시보드'},B('xlsx','엑셀 다운로드','btn primary'))}<div class="toolbar statistics-toolbar"><div class="tabs">${['전체','구매','수출'].map(k=>B('kind',k,'btn '+(kind===k?'primary':''),`data-kind="${k}" aria-pressed="${kind===k}"`)).join('')}</div><span class="small">${E(event)} G-FAIR · ${kind==='전체'?'구매 + 수출':kind} 누적 통계</span></div><div class="statistics-top"><article class="statistics-card"><h3>바이어 수 및 출결</h3><strong class="statistics-number">${d.attendance.reduce((a,b)=>a+b,0)}<small>명</small></strong>${dashboardStack(['미출석','출석'],d.attendance,['#919191','#a9a9a9'])}</article><article class="statistics-card"><div class="statistics-chart-title"><h3>누적 계약 추진 현황</h3><small>단위: 건</small></div><div class="statistics-progress" role="img" aria-label="검토중 ${progress[0]}건, 샘플/견적 협의 ${progress[1]}건, 계약 협의 ${progress[2]}건, 계약 체결 ${progress[3]}건">${['검토중','샘플·견적 협의','계약 협의','계약 체결'].map((t,i)=>`<div><span style="height:${progress[i]/Math.max(...progress)*100}px"></span><small>${t}</small><b>${progress[i]}</b></div>`).join('')}</div></article><div class="statistics-summary">${[['누적 상담 건수',d.count,'건','clipboard-list','#a9a9a9'],['누적 계약 추진 건수',d.contracts,'건','pen-line','#b8b8b8'],['누적 상담액',d.money,'','hand-coins','#949494'],['계약 추진 중인 금액',d.contractMoney,'','wallet','#9a9a9a']].map(([t,v,u,icon,color])=>`<article class="statistics-card statistics-metric"><span class="statistics-icon" style="background:${color}"><i data-lucide="${icon}" aria-hidden="true"></i></span><div><h3>${t}</h3><strong class="${typeof v==='string'?'statistics-money':'statistics-number'}">${E(v)}<small>${u}</small></strong></div></article>`).join('')}</div><article class="statistics-card"><h3>참여 기업</h3><div class="statistics-participation">${[['참여',d.companies[0],'building-2'],['불참',d.companies[1],'building-2']].map(([t,v,icon],i)=>`<div class="${i?'inactive':''}"><i data-lucide="${icon}" aria-hidden="true"></i><span>${t}</span><strong>${v}<small>개사</small></strong></div>`).join('')}</div></article><article class="statistics-card"><h3>참여 바이어</h3><div class="statistics-participation">${[['참여',d.buyers[0]],['불참',d.buyers[1]]].map(([t,v],i)=>`<div class="${i?'inactive':''}"><i data-lucide="users" aria-hidden="true"></i><span>${t}</span><strong>${v}<small>명</small></strong></div>`).join('')}</div></article><article class="statistics-card statistics-journals">${d.buy?statisticsJournal('구매'):''}${d.exp?statisticsJournal('수출'):''}</article></div>${d.buy?statisticsRankSection('국내 바이어','#919191'):''}${d.exp?statisticsRankSection('해외 바이어','#a9a9a9'):''}${statisticsRankSection('참가기업','#949494')}${statisticsRankSection('품목별','#b8b8b8')}<p class="small statistics-footnote">KRW와 USD는 환산 없이 구분 표시됩니다.</p>`};
const statisticsExport=exportRows;
exportRows=function(){if(current!=='STA-01')return statisticsExport();const d=statisticsData(),out=[['구분',kind],['행사',event],['데이터 기준','조회 결과'],['지표','값','단위'],['바이어 수',d.attendance.reduce((a,b)=>a+b,0),'명'],['미출석',d.attendance[0],'명'],['출석',d.attendance[1],'명'],['누적 상담 건수',d.count,'건'],['누적 계약 추진 건수',d.contracts,'건']];for(const [enabled,type,values] of [[d.buy,'구매',[320000000,90000000,'KRW']],[d.exp,'수출',[1800000,600000,'USD']]])if(enabled){out.push([type+' 누적 상담액',values[0],values[2]],[type+' 계약 추진액',values[1],values[2]]);const status=dashboardExample[type==='구매'?'buy':'export'].status;out.push([type+' 일지 승인 완료',status[0],'건'],[type+' 일지 승인 요청',status[1],'건'],[type+' 일지 반려',status[2],'건'])}out.push(['참여기업',d.companies[0],'개사'],['불참기업',d.companies[1],'개사'],['참여바이어',d.buyers[0],'명'],['불참바이어',d.buyers[1],'명']);const progress=kind==='구매'?[20,16,14,10]:kind==='수출'?[30,24,22,18]:[50,40,36,28];['검토중','샘플·견적 협의','계약 협의','계약 체결'].forEach((t,i)=>out.push([t,progress[i],'건']));for(const group of [...(d.buy?['국내 바이어']:[]),...(d.exp?['해외 바이어']:[]),'참가기업','품목별']){out.push([],[group+' TOP5',group==='품목별'?statisticsCategory:''],['순위','대상','상담 건수','상담 금액','통화','수출 상담 금액(USD)']);statisticsRanks(group).forEach((r,i)=>out.push([i+1,r.name,r.count,r.amount,r.currency,r.exportAmount||'']))}return out};
root.addEventListener('change',ev=>{if(ev.target.id==='statistics-category'){statisticsCategory=ev.target.value;render()}});
const annualState={start:2024,end:2026,type:'전체',buyer:'전체'};
const annualYears=[2024,2025,2026],annualColors=['#6e6e6e','#7a7a7a','#838383','#b4b4b4'];
const annualRecords=annualYears.flatMap((year,y)=>Array.from({length:6},(_,i)=>{const type=i<3?'구매':'수출',name=(i<3?'국내바이어 ':'해외바이어 ')+String.fromCharCode(65+i%3),attended=!((i+y)%5===0),count=attended?40+i*16+y*12:0,approved=Math.floor(count*.78),pending=Math.floor(count*.17);return {year,id:(i<3?'D-':'F-')+(i%3+1),name,type,attended,count,approved,pending,rejected:count-approved-pending,contracts:Math.round(count*.12),amount:count*(type==='구매'?100000:1500),contractAmount:Math.round(count*.12)*(type==='구매'?50000:800),currency:type==='구매'?'KRW':'USD',items:[Math.floor(count*.35),Math.floor(count*.25),Math.floor(count*.2),count-Math.floor(count*.35)-Math.floor(count*.25)-Math.floor(count*.2)]}}));
function annualSelected(){return annualRecords.filter(r=>(current==='STA-03'||r.id!=='F-4')&&r.year>=annualState.start&&r.year<=annualState.end&&(annualState.type==='전체'||r.type===annualState.type)&&(current!=='STA-03'||annualState.buyer==='전체'||r.id===annualState.buyer))}
function annualTotals(rr){const sum=key=>rr.reduce((a,r)=>a+r[key],0);return {count:sum('count'),approved:sum('approved'),pending:sum('pending'),rejected:sum('rejected'),contracts:sum('contracts'),registered:rr.length,attendance:rr.filter(r=>r.attended).length,domestic:rr.filter(r=>r.type==='구매'&&r.attended).length,foreign:rr.filter(r=>r.type==='수출'&&r.attended).length,krw:rr.filter(r=>r.currency==='KRW').reduce((a,r)=>a+r.amount,0),usd:rr.filter(r=>r.currency==='USD').reduce((a,r)=>a+r.amount,0),contractKrw:rr.filter(r=>r.currency==='KRW').reduce((a,r)=>a+r.contractAmount,0),contractUsd:rr.filter(r=>r.currency==='USD').reduce((a,r)=>a+r.contractAmount,0)}}
function annualChart(title,labels,series,mode='bar',unit='건'){const w=650,h=270,left=65,right=20,top=35,bottom=45,width=w-left-right,height=h-top-bottom,maxRaw=Math.max(1,...(mode==='stack'?labels.map((_,i)=>series.reduce((a,s)=>a+s.values[i],0)):series.flatMap(s=>s.values))),max=Math.ceil(maxRaw/4)*4,x=i=>left+(i+.5)*width/labels.length,y=v=>top+height-v/max*height;const grid=Array.from({length:5},(_,i)=>{const v=max*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e7e7e7" stroke-dasharray="4 4"/><text x="${left-9}" y="${y(v)+4}" text-anchor="end">${v.toLocaleString()}</text>`}).join('');let marks='';if(mode==='line')marks=series.map(s=>`<polyline fill="none" stroke="${s.color}" stroke-width="3" points="${s.values.map((v,i)=>x(i)+','+y(v)).join(' ')}"/>${s.values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="5" fill="${s.color}"><title>${labels[i]} ${s.name} ${v.toLocaleString()}${unit}</title></circle><text x="${x(i)}" y="${y(v)-12}" text-anchor="middle" fill="${s.color}">${v.toLocaleString()}</text>`).join('')}`).join('');else marks=labels.map((label,i)=>{const span=Math.min(100,width/labels.length*.65);let cumulative=0;return series.map((s,j)=>{const v=s.values[i],stack=mode==='stack',bw=stack?span:span/series.length,bx=x(i)-span/2+(stack?0:j*bw),by=y(stack?cumulative+v:v);cumulative+=v;return `<rect x="${bx}" y="${by}" width="${bw-3}" height="${v/max*height}" rx="3" fill="${s.color}"><title>${label} ${s.name} ${v.toLocaleString()}${unit}</title></rect>${!stack?`<text x="${bx+bw/2}" y="${by-8}" text-anchor="middle" fill="${s.color}">${v.toLocaleString()}</text>`:v?`<text x="${bx+bw/2}" y="${by+v/max*height/2+4}" text-anchor="middle" fill="#ffffff">${v}</text>`:''}`}).join('')+(mode==='stack'?`<text x="${x(i)}" y="${y(cumulative)-10}" text-anchor="middle">${cumulative}</text>`:'')}).join('');return `<article class="annual-chart"><div class="statistics-chart-title"><h3>${E(title)}</h3><small>단위: ${E(unit)}</small></div><div class="annual-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${E(s.name)}</span>`).join('')}</div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${E(title+': '+labels.map((l,i)=>l+' '+series.map(s=>s.name+' '+s.values[i]+unit).join(', ')).join('; '))}">${grid}${marks}${labels.map((t,i)=>`<text x="${x(i)}" y="${h-14}" text-anchor="middle">${E(t)}</text>`).join('')}</svg></article>`}
function annualDonut(title,labels,values,unit='건'){const total=values.reduce((a,b)=>a+b,0);let end=0;const gradient=values.map((v,i)=>{const start=end;end+=total?v/total*100:0;return `${annualColors[i%4]} ${start}% ${end}%`}).join(',');return `<article class="annual-chart"><h3>${E(title)}</h3><div class="annual-donut-layout"><div class="overview-donut annual-donut" style="background:${total?'conic-gradient('+gradient+')':'#f0f0f0'}" role="img" aria-label="${E(labels.map((t,i)=>t+' '+values[i]+unit).join(', '))}"><span>${total.toLocaleString()}<small>${unit}</small></span></div><ul class="annual-donut-legend">${labels.map((t,i)=>`<li><i style="background:${annualColors[i%4]}"></i><span>${E(t)}</span><b>${values[i].toLocaleString()}${unit}</b><small>${total?(values[i]/total*100).toFixed(1):0}%</small></li>`).join('')}</ul></div></article>`}
function annualFilter(){const people=annualRecords.filter(r=>r.year===2026&&(annualState.type==='전체'||r.type===annualState.type));return `<form id="annual-filter" class="panel filters">${F('시작 연도',`<select name="start">${annualYears.map(y=>`<option value="${y}" ${y===annualState.start?'selected':''}>${y}년</option>`).join('')}</select>`)}${F('종료 연도',`<select name="end">${annualYears.map(y=>`<option value="${y}" ${y===annualState.end?'selected':''}>${y}년</option>`).join('')}</select>`)}${F('상담 구분',`<select name="type">${O(['전체','구매','수출'],annualState.type)}</select>`)}${current==='STA-03'?F('바이어',`<select name="buyer"><option value="전체">전체 바이어</option>${people.map(r=>`<option value="${r.id}" ${r.id===annualState.buyer?'selected':''}>${E(r.name)} (${r.id})</option>`).join('')}</select>`):''}<div class="row"><button type="submit" class="btn primary">조회</button>${B('annual-reset','초기화')}</div></form>`}
function annualDetailTable(rr){const cols=current==='STA-03'?['연도','고유 번호','바이어명','구분','참가 상태','상담 건수','계약 추진 건수','상담액','계약 추진액','일지 승인/대기/반려']:['연도','상담 건수','계약 추진 건수','일지 등록 건수','승인','대기','반려','상담액 KRW','상담액 USD','계약 추진액 KRW','계약 추진액 USD'];const values=current==='STA-03'?rr.map(r=>[r.year,r.id,r.name,r.type,r.attended?'참가':'불참',r.count,r.contracts,r.amount.toLocaleString()+' '+r.currency,r.contractAmount.toLocaleString()+' '+r.currency,`${r.approved} / ${r.pending} / ${r.rejected}`]):annualYears.filter(y=>y>=annualState.start&&y<=annualState.end).map(y=>{const t=annualTotals(rr.filter(r=>r.year===y));return [y,t.count,t.contracts,t.count,t.approved,t.pending,t.rejected,t.krw.toLocaleString(),t.usd.toLocaleString(),t.contractKrw.toLocaleString(),t.contractUsd.toLocaleString()]});return {cols,values}}
function annualPage(s){const rr=annualSelected(),t=annualTotals(rr),years=annualYears.filter(y=>y>=annualState.start&&y<=annualState.end),perYear=years.map(y=>annualTotals(rr.filter(r=>r.year===y))),series=(name,key,color)=>({name,values:perYear.map(t=>t[key]),color}),tableData=annualDetailTable(rr),buyerPage=s.id==='STA-03';const tiles=buyerPage?[['참가 이력',t.registered,'회'],['실참가',t.attendance,'회'],['미참가',t.registered-t.attendance,'회'],['상담 건수',t.count,'건'],['계약 추진 건수',t.contracts,'건']]:[['누적 상담 건수',t.count,'건'],['계약 추진 건수',t.contracts,'건'],['일지 등록 건수',t.count,'건'],['참가 바이어(연인원)',t.attendance,'명'],['일지 승인율',t.count?(t.approved/t.count*100).toFixed(1):0,'%']];return `${head(s,B('xlsx','엑셀 다운로드','btn primary'))}${annualFilter()}<div class="annual-period"><strong>${annualState.start} ~ ${annualState.end}년 · ${annualState.type} ${buyerPage&&annualState.buyer!=='전체'?'· '+E(rr[0]?.name||'선택 바이어'):''}</strong><span>연도별 행사 집계</span></div><div class="kpis overview-kpis">${tiles.map(([label,value,unit])=>`<article class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value.toLocaleString()}<small>${unit}</small></div><div class="kpi-note">선택 연도 범위 기준</div></article>`).join('')}</div><section class="panel pad"><h2>${buyerPage?'연도별 바이어 참가 현황':'연도별 주요 실적 추이'}</h2><div class="annual-chart-grid">${buyerPage?annualChart('참여 바이어 추이',years,[series('국내 바이어','domestic',annualColors[0]),series('해외 바이어','foreign',annualColors[1])],'stack','명'):annualChart('계약 추진 건수 추이',years,[series('계약 추진 건수','contracts',annualColors[0])],'line')}${annualChart('상담일지 상태 추이',years,[series('승인','approved',annualColors[0]),series('대기','pending',annualColors[2]),series('반려','rejected',annualColors[3])],'stack')}${annualChart('상담 건수 추이',years,[series('상담 건수','count',annualColors[1])],'line')}</div></section><section class="panel pad"><h2>${buyerPage?'연도별 바이어 상담 성과':'연도별 금액 성과'}</h2><div class="annual-chart-grid two">${annualChart('상담액·계약 추진액 (KRW)',years,[series('상담액','krw',annualColors[0]),series('계약 추진액','contractKrw',annualColors[1])],'bar','KRW')}${annualChart('상담액·계약 추진액 (USD)',years,[series('상담액','usd',annualColors[0]),series('계약 추진액','contractUsd',annualColors[1])],'bar','USD')}</div><p class="small">원화와 달러는 환산 없이 별도 집계합니다.</p></section><section class="panel pad"><h2>상태별 구성</h2><div class="annual-chart-grid two">${annualDonut('상담일지 처리 상태',['승인','대기','반려'],[t.approved,t.pending,t.rejected])}${annualDonut('바이어 참가 상태',['참가','불참'],[t.attendance,t.registered-t.attendance],'회')}</div></section><section class="panel pad"><h2>연도별 품목별 상담 건수</h2>${annualChart('품목별 상담 추이',['리빙','뷰티','식품','기타'],years.map((year,i)=>({name:year+'년',values:[0,1,2,3].map(k=>rr.filter(r=>r.year===year).reduce((a,r)=>a+r.items[k],0)),color:annualColors[i]})))}</section><section class="panel"><div class="panelhead"><h2>${buyerPage?'연도별 바이어 참가 이력 및 상담 성과':'연도별 실적 상세'}</h2><span>${tableData.values.length}건</span></div><div class="tablewrap"><table><thead><tr>${tableData.cols.map(c=>`<th>${E(c)}</th>`).join('')}</tr></thead><tbody>${tableData.values.length?tableData.values.map(r=>`<tr>${r.map(v=>`<td>${E(v)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${tableData.cols.length}">조회 결과가 없습니다.</td></tr>`}</tbody></table></div></section><p class="small">참가 인원은 연도별 중복 참가를 포함한 연인원입니다. 참고 PPT의 수치는 이며 실제 운영 자료 연계 전입니다.</p>`}
const annualList=list;
list=function(s){return ['STA-02','STA-03'].includes(s.id)?annualPage(s):annualList(s)};
const annualExport=exportRows;
exportRows=function(){if(!['STA-02','STA-03'].includes(current))return annualExport();const rr=annualSelected(),d=annualDetailTable(rr);return [['화면',map.get(current).title],['연도 범위',annualState.start,annualState.end],['상담 구분',annualState.type],['바이어',current==='STA-03'?annualState.buyer:'전체'],['데이터 기준','조회 결과'],[],d.cols,...d.values,[],['품목','연도','상담 건수'],...annualYears.filter(y=>y>=annualState.start&&y<=annualState.end).flatMap(y=>['리빙','뷰티','식품','기타'].map((label,k)=>[label,y,rr.filter(r=>r.year===y).reduce((a,r)=>a+r.items[k],0)]))]};
root.addEventListener('submit',ev=>{if(ev.target.id!=='annual-filter')return;const fd=new FormData(ev.target),start=Number(fd.get('start')),end=Number(fd.get('end'));if(start>end)return toast('종료 연도는 시작 연도보다 같거나 늦어야 합니다.');Object.assign(annualState,{start,end,type:fd.get('type'),buyer:fd.get('buyer')||'전체'});render()});
root.addEventListener('click',ev=>{if(ev.target.closest('[data-action=annual-reset]')){Object.assign(annualState,{start:2024,end:2026,type:'전체',buyer:'전체'});render()}});
root.addEventListener('change',ev=>{if(ev.target.closest('#annual-filter')&&ev.target.name==='type'&&current==='STA-03'){const select=document.querySelector('#annual-filter [name=buyer]'),type=ev.target.value;select.innerHTML='<option value="전체">전체 바이어</option>'+annualRecords.filter(r=>r.year===2026&&(type==='전체'||r.type===type)).map(r=>`<option value="${r.id}">${E(r.name)} (${r.id})</option>`).join('')}});

function annualContractCombo(rr,years){const currency=annualState.type==='구매'?'KRW':'USD',key=currency==='KRW'?'contractKrw':'contractUsd',unit=currency==='KRW'?'백만원':'백만 USD',values=years.map(year=>annualTotals(rr.filter(r=>r.year===year))[key]/1000000),previous=year=>annualTotals(annualRecords.filter(r=>r.id!=='F-4'&&r.year===year-1&&(annualState.type==='전체'||r.type===annualState.type)))[key]/1000000,rates=years.map((year,i)=>{const old=previous(year);return old?(values[i]-old)/old*100:null});const w=650,h=290,left=65,right=60,top=40,bottom=45,height=h-top-bottom,width=w-left-right,max=Math.max(.001,...values)*1.25,lo=Math.min(0,...rates.filter(v=>v!==null)),hi=Math.max(10,...rates.filter(v=>v!==null))*1.2,x=i=>left+(i+.5)*width/years.length,y=v=>top+height-v/max*height,yr=v=>top+height-(v-lo)/(hi-lo)*height,fmt=v=>Number(v.toFixed(4)).toLocaleString();return `<article class="annual-chart annual-combo"><div class="statistics-chart-title"><h3>계약 추진 금액 추이</h3><small>단위: ${unit} / %</small></div><div class="annual-legend"><span><i style="background:#6e6e6e"></i>계약 추진 금액 (${unit})</span><span><i style="background:#7a7a7a"></i>전년 대비 증감률 (%)</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${E(years.map((year,i)=>year+'년 계약 추진 금액 '+fmt(values[i])+unit+', 전년 대비 '+(rates[i]===null?'비교자료 없음':rates[i].toFixed(1)+'%')).join('; '))}">${Array.from({length:5},(_,i)=>{const amount=max*i/4,rate=lo+(hi-lo)*i/4,cy=top+height-i/4*height;return `<line x1="${left}" x2="${w-right}" y1="${cy}" y2="${cy}" stroke="#e7e7e7" stroke-dasharray="4 4"/><text x="${left-8}" y="${cy+4}" text-anchor="end">${fmt(amount)}</text><text x="${w-right+9}" y="${cy+4}">${rate.toFixed(0)}%</text>`}).join('')}${values.map((v,i)=>`<rect x="${x(i)-23}" y="${y(v)}" width="46" height="${v/max*height}" fill="#6e6e6e" rx="3"/><text x="${x(i)}" y="${y(v)-8}" text-anchor="middle">${fmt(v)}</text>`).join('')}<polyline fill="none" stroke="#7a7a7a" stroke-width="3" points="${rates.map((v,i)=>v===null?'':x(i)+','+yr(v)).filter(Boolean).join(' ')}"/>${rates.map((v,i)=>v===null?'':`<circle cx="${x(i)}" cy="${yr(v)}" r="5" fill="white" stroke="#7a7a7a" stroke-width="3"/><text x="${x(i)}" y="${yr(v)-12}" text-anchor="middle">${v.toFixed(1)}%</text>`).join('')}${years.map((year,i)=>`<text x="${x(i)}" y="${h-14}" text-anchor="middle">${year}</text>`).join('')}</svg><p class="small">전년도 자료가 없는 연도는 증감률을 표시하지 않습니다. ${currency} 기준이며 통화 합산은 하지 않습니다.</p></article>`}
const annualChartPage=annualPage;
annualPage=function(s){let html=annualChartPage(s);if(s.id!=='STA-02')return html;const rr=annualSelected(),years=annualYears.filter(y=>y>=annualState.start&&y<=annualState.end),counts=years.map(y=>annualTotals(rr.filter(r=>r.year===y)).count);const extra=`<section class="panel pad"><h2>계약 추진 금액 및 상담일지 비교</h2><div class="annual-chart-grid two">${annualContractCombo(rr,years)}${annualChart('연도별 상담일지 등록 건수 및 상담 건수 추이',years,[{name:'상담일지 등록 건수',values:counts,color:annualColors[0]},{name:'상담 건수',values:counts,color:annualColors[1]}])}</div><p class="small">현재 집계는 상담 건별 일지 1건을 기준으로 두 건수가 같습니다.</p></section>`;html=html.replace('<section class="panel pad"><h2>연도별 금액 성과</h2>',extra+'<section class="panel pad"><h2>연도별 금액 성과</h2>');return html.replace('<section class="panel pad"><h2>연도별 품목별 상담 건수</h2>','<section class="panel pad annual-items-compact"><h2>연도별 품목별 상담 건수</h2>')};

// Additional Chinese buyer participates in the example yearly statistics.
for(const year of annualYears){const source=annualRecords.find(r=>r.year===year&&r.id==='F-2');annualRecords.push({...source,id:'F-4',name:'해외바이어 D',country:'중국',items:[...source.items]})}
for(const r of annualRecords)r.country=r.type==='구매'?'대한민국':{'F-1':'미국','F-2':'일본','F-3':'베트남','F-4':'중국'}[r.id];
function buyerParticipation(){const rr=annualSelected(),attended=rr.filter(r=>r.attended),people=[...new Map(attended.map(r=>[r.id,r])).values()],countries=[...new Set(people.map(r=>r.country))],countryCounts=countries.map(c=>people.filter(r=>r.country===c).length),items=[0,1,2,3].map(k=>attended.reduce((a,r)=>a+r.items[k],0)),years=annualYears.filter(y=>y>=annualState.start&&y<=annualState.end);return {rr,attended,people,countries,countryCounts,items,years}}
const buyerOnlyAnnual=annualPage;
annualPage=function(s){if(s.id!=='STA-03')return buyerOnlyAnnual(s);const d=buyerParticipation(),perYear=d.years.map(y=>d.attended.filter(r=>r.year===y)),series=(name,type,color)=>({name,color,values:perYear.map(rr=>rr.filter(r=>r.type===type).length)}),tiles=[['참여 바이어(실인원)',d.people.length,'명'],['국내 바이어',d.people.filter(r=>r.type==='구매').length,'명'],['해외 바이어',d.people.filter(r=>r.type==='수출').length,'명'],['참여 바이어(연인원)',d.attended.length,'명'],['참여 국가',d.countries.length,'개국']];return `${head({...s,summary:'연도별 바이어 참가 이력과 국가·품목별 참여 특성을 확인한다.'},B('xlsx','엑셀 다운로드','btn primary'))}${annualFilter()}<div class="annual-period"><strong>${annualState.start} ~ ${annualState.end}년 · ${annualState.type}${annualState.buyer!=='전체'?' · '+E(d.rr[0]?.name||'선택 바이어'):''}</strong><span>바이어 통계</span></div><div class="kpis overview-kpis">${tiles.map(([label,value,unit])=>`<article class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-note">선택 기간 내 참가 기준</div></article>`).join('')}</div><section class="panel pad"><h2>연도별 참여 바이어 통계 추이</h2><div class="annual-chart-grid two">${annualChart('국내·해외 바이어 참여 추이',d.years,[series('국내 바이어','구매',annualColors[0]),series('해외 바이어','수출',annualColors[1])],'stack','명')}${annualChart('참여·미참여 바이어 추이',d.years,[{name:'참여',color:annualColors[0],values:d.years.map(y=>d.rr.filter(r=>r.year===y&&r.attended).length)},{name:'미참여',color:annualColors[2],values:d.years.map(y=>d.rr.filter(r=>r.year===y&&!r.attended).length)}],'bar','명')}</div></section><section class="panel pad"><h2>국가별 바이어 참여 통계 및 품목별 상담 비중</h2><div class="annual-chart-grid two">${annualDonut('국가별 참여 바이어 비중',d.countries,d.countryCounts,'명')}${annualDonut('바이어 품목별 상담 비중',['리빙','뷰티','식품','기타'],d.items,'건')}</div><p class="small">국가별 비중: 선택 기간 내 참가 바이어를 고유 번호로 중복 제외한 실인원 기준. 품목별 비중: 해당 바이어들의 선택 기간 상담 건수 기준.</p></section><section class="panel pad annual-country-compact"><h2>연도별 국가별 바이어 참여 추이</h2>${annualChart('국가별 참여 바이어 수',d.years,d.countries.map((country,i)=>({name:country,color:annualColors[i%annualColors.length],values:d.years.map(y=>d.attended.filter(r=>r.year===y&&r.country===country).length)})),'bar','명')}</section><section class="panel"><div class="panelhead"><h2>연도별 바이어 참가 이력</h2><span>${d.rr.length}건</span></div><div class="tablewrap"><table><thead><tr>${['연도','고유 번호','바이어명','국가','바이어 구분','참가 상태','주요 상담 품목','상담 건수'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${d.rr.map(r=>`<tr><td>${r.year}</td><td>${E(r.id)}</td><td>${E(r.name)}</td><td>${E(r.country)}</td><td>${r.type==='구매'?'국내':'해외'}</td><td>${badge(r.attended?'참가':'미참가')}</td><td>${r.count?['리빙','뷰티','식품','기타'][r.items.indexOf(Math.max(...r.items))]:'해당 없음'}</td><td>${r.count.toLocaleString()}건</td></tr>`).join('')||'<tr><td colspan="8">조회 결과가 없습니다.</td></tr>'}</tbody></table></div></section><p class="small">실인원은 고유 번호로 중복 제외하며, 연인원은 연도별 참가를 누적합니다. 계약·금액·상담일지 상태 통계는 연도별 상담실적 통계에서 확인하세요.</p>`};
const buyerOnlyExport=exportRows;
exportRows=function(){if(current!=='STA-03')return buyerOnlyExport();const d=buyerParticipation();return [['화면','연도별 바이어 통계'],['연도 범위',annualState.start,annualState.end],['상담 구분',annualState.type],['바이어',annualState.buyer],['데이터 기준','바이어 통계'],[],['국가','참가 바이어 실인원','비중(%)'],...d.countries.map((c,i)=>[c,d.countryCounts[i],d.people.length?Number((d.countryCounts[i]/d.people.length*100).toFixed(1)):0]),[],['품목','상담 건수','비중(%)'],...['리빙','뷰티','식품','기타'].map((t,i)=>[t,d.items[i],d.items.reduce((a,b)=>a+b,0)?Number((d.items[i]/d.items.reduce((a,b)=>a+b,0)*100).toFixed(1)):0]),[],['연도','국내 참여 바이어','해외 참여 바이어','참여','미참여'],...d.years.map(y=>{const rr=d.rr.filter(r=>r.year===y);return [y,rr.filter(r=>r.attended&&r.type==='구매').length,rr.filter(r=>r.attended&&r.type==='수출').length,rr.filter(r=>r.attended).length,rr.filter(r=>!r.attended).length]}),[],['연도','고유 번호','바이어명','국가','구분','참가 상태','상담 건수'],...d.rr.map(r=>[r.year,r.id,r.name,r.country,r.type,r.attended?'참가':'미참가',r.count])]};

const buyerPageWithoutHistory=annualPage;
annualPage=function(s){const html=buyerPageWithoutHistory(s);return s.id==='STA-03'?html.replace(/<section class="panel"><div class="panelhead"><h2>연도별 바이어 참가 이력<\/h2>[\s\S]*?<\/section>/,''):html};
root.addEventListener('click',ev=>{if(ev.target.closest('[data-action=my-info]')){if(['buyOperator','exportOperator'].includes(role)){nav('COM-06');return}modal('내정보',`<dl class="detaildata"><dt>사용자 유형</dt><dd>${E(roles[role])}</dd><dt>선택 행사</dt><dd>G-FAIR KOREA ${E(event)}</dd><dt>계정 상태</dt><dd>검토용 계정</dd></dl><p class="small" style="margin-top:18px">실제 계정 정보는 회원 연계 후 제공됩니다.</p>`);}});
const annualPerformancePage=annualPage;
annualPage=function(s){const html=annualPerformancePage(s);if(s.id!=='STA-02')return html;const match=html.match(/<div class="head-actions">([\s\S]*?)<\/div><\/div>(<form id="annual-filter")/);return match?html.replace(match[0],`</div><div class="row" style="justify-content:flex-end;margin:0 0 12px">${match[1]}</div>${match[2]}`):html};
const surveyTargets=['국내 바이어','해외 바이어','통역원'],surveyTypes=['단일응답형','복수응답형','단답형','서술형','척도형'];
const surveyClone=v=>JSON.parse(JSON.stringify(v));
function surveyQuestion(type='단일응답형',title=''){return {title,type,required:true,options:(type==='척도형'?['매우 불만족','불만족','보통','만족','매우 만족']:['예','아니오']).map(label=>({label,extra:false}))}}
function surveySeed(){return [2025,2026].flatMap(year=>surveyTargets.map((target,t)=>{const id='SUR-'+year+'-'+t,groups=[{title:'행사 운영 평가',questions:[surveyQuestion('척도형','행사 운영 전반에 얼마나 만족하셨나요?'),surveyQuestion('단일응답형','다음 행사에도 참여하시겠습니까?'),surveyQuestion('복수응답형','도움이 되었던 서비스를 선택해주세요.')]},{title:'개선 의견',questions:[surveyQuestion('단답형','가장 좋았던 점을 한 줄로 적어주세요.'),surveyQuestion('서술형','개선이 필요한 사항을 자유롭게 적어주세요.')]}];groups[0].questions[2].options=[{label:'상담 운영',extra:false},{label:'정보 안내',extra:false},{label:'현장 지원',extra:false},{label:'기타',extra:true}];return {id,year,target,title:year+'년 G-FAIR '+target+' 만족도 조사',minutes:5,intro:'행사 운영 개선을 위해 의견을 남겨주세요. 응답은 만족도 조사에 활용됩니다.',outro:'설문에 참여해 주셔서 감사합니다.',active:true,start:year+'-10-01',end:year+'-12-31',created:year+'-09-01',audience:20+t*10,groups,responses:Array.from({length:8+t*2},(_,i)=>({id:id+'-R'+i,name:target+' '+String.fromCharCode(65+i),userId:'DEMO-'+t+'-'+String(i+1).padStart(3,'0'),date:year+'-10-'+String(i+1).padStart(2,'0')+' 14:30',helper:t===1?'통역원 '+String.fromCharCode(65+i%3):'',answers:{'0-0':String(2+i%3),'0-1':String(i%2),'0-2':i%2?['0','2']:['1'],'1-0':'친절한 안내가 좋았습니다.','1-1':i%2?'상담 시간을 조금 더 늘려주세요.':'현장 안내가 잘 되어 만족합니다.'},extras:{}}))}}))}
let surveyStore=surveySeed();try{const stored=JSON.parse(localStorage.getItem('gfair-surveys-v1'));if(Array.isArray(stored)&&stored.every(s=>s.id&&Array.isArray(s.groups)&&Array.isArray(s.responses)))surveyStore=stored}catch{}
function surveyPersist(){try{localStorage.setItem('gfair-surveys-v1',JSON.stringify(surveyStore));return true}catch{toast('이 기기의 저장 공간을 사용할 수 없습니다.');return false}}
const surveyUi={manage:'list',response:'list',editor:null,id:null,tab:'stats',filters:{year:'전체',target:'전체',active:'전체',query:''},responseFilters:{year:'2026',target:'전체',query:''},from:'',to:'',historyPage:1,historySize:10};
function surveyFind(id){return surveyStore.find(s=>s.id===id)}
function surveyField(label,name,value,type='text',attrs=''){return F(label,I(name,type,value,attrs))}
function surveyListFilter(response=false){const f=response?surveyUi.responseFilters:surveyUi.filters,years=[...new Set(surveyStore.map(s=>s.year))].sort((a,b)=>b-a);return `<form id="survey-list-filter" data-response="${response}" class="panel filters">${F('연도',`<select name="year">${O(['전체',...years.map(String)],f.year)}</select>`)}${F('대상',`<select name="target">${O(['전체',...surveyTargets],f.target)}</select>`)}${!response?F('사용여부',`<select name="active">${O(['전체','사용','미사용'],f.active)}</select>`):''}${surveyField('설문제목','query',f.query,'search','placeholder="설문제목 입력"')}<div class="row"><button type="submit" class="btn primary">검색</button>${B(response?'sur-response-reset':'sur-manage-reset','초기화')}</div></form>`}
function surveyListed(response=false){const f=response?surveyUi.responseFilters:surveyUi.filters;return surveyStore.filter(s=>(f.year==='전체'||String(s.year)===f.year)&&(f.target==='전체'||s.target===f.target)&&(response||f.active==='전체'||s.active===(f.active==='사용'))&&s.title.includes(f.query.trim())).sort((a,b)=>a.created.localeCompare(b.created)||a.id.localeCompare(b.id))}
function surveyManageList(s){const rr=surveyListed();return `${head({...s,title:'설문관리',summary:'국내 바이어·해외 바이어·통역원별 설문을 등록하고 미리보기한다.'},B('sur-create','등록','btn primary'))}${surveyListFilter()}<section class="panel"><div class="panelhead"><h2>설문 목록</h2><span>${rr.length}건 · 이 기기에서 저장되는 검토용 설문</span></div><div class="tablewrap"><table class="survey-action-list"><colgroup><col style="width:46px"><col style="width:60px"><col style="width:100px"><col><col style="width:90px"><col style="width:180px"><col style="width:84px"><col style="width:74px"><col style="width:132px"></colgroup><thead><tr><th>No.</th><th>연도</th><th>대상</th><th>설문제목</th><th>예상 소요시간</th><th>조사기간</th><th>미리보기</th><th>사용여부</th><th>관리</th></tr></thead><tbody>${rr.map((q,i)=>`<tr><td>${i+1}</td><td>${q.year}</td><td>${E(q.target)}</td><td>${B('sur-edit',q.title,'btn ghost',`data-id="${E(q.id)}"`)}</td><td>${q.minutes}분</td><td>${q.start} ~ ${q.end}</td><td>${B('sur-preview','미리보기','btn',`data-id="${E(q.id)}"`)}</td><td>${B('sur-use',q.active?'사용':'미사용','btn ghost',`data-id="${E(q.id)}"`)}</td><td><div class="row">${B('sur-copy','복사','btn',`data-id="${E(q.id)}"`)}${B('sur-delete','삭제','btn danger',`data-id="${E(q.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="9">조회된 설문이 없습니다.</td></tr>'}</tbody></table></div></section>`}
function surveyEditor(s){const q=surveyUi.editor,locked=q.responses.length>0;return `${head({...s,title:'설문관리 '+(surveyFind(q.id)?'상세':'등록'),summary:'기본정보와 그룹별 문항을 작성한 후 미리보기로 확인한다.'},B('sur-manage-back','목록으로'))}${locked?'<div class="notice amber">응답이 있는 설문은 문항을 변경할 수 없습니다. 복사하여 새 설문으로 등록하세요.</div>':''}<form id="survey-editor"><fieldset ${locked?'disabled':''} class="survey-fieldset"><section class="panel"><div class="panelhead"><h2>기본정보</h2></div><div class="pad survey-basic formgrid">${surveyField('설문제목','title',q.title,'text','required')}${surveyField('예상 소요시간(분)','minutes',q.minutes,'number','min="1" max="120" required')}${F('연도',`<select name="year">${O(['2025','2026','2027'],String(q.year))}</select>`)}${F('대상',`<select name="target">${O(surveyTargets,q.target)}</select>`)}${surveyField('조사 시작일','start',q.start,'date','required')}${surveyField('조사 종료일','end',q.end,'date','required')}${F('사용여부',`<div class="row"><label><input type="radio" name="active" value="true" ${q.active?'checked':''}> 사용</label><label><input type="radio" name="active" value="false" ${!q.active?'checked':''}> 미사용</label></div>`)}${surveyField('조사 대상 인원','audience',q.audience,'number','min="0" required')}${F('상단 문구',`<textarea name="intro">${E(q.intro)}</textarea>`,false,true)}${F('마무리 문구',`<textarea name="outro">${E(q.outro)}</textarea>`,false,true)}</div></section><section class="panel pad"><div class="survey-section-head"><h2>설문정보</h2>${B('sur-group-add','그룹추가')}</div>${q.groups.map((g,gi)=>`<details class="survey-group" open><summary>그룹 ${gi+1} · ${E(g.title||'새 그룹')}</summary><div class="survey-group-body"><div class="survey-section-head">${F('그룹명',I('g-'+gi,'text',g.title,'required'))}${gi?B('sur-group-delete','그룹삭제','btn danger',`data-group="${gi}"`):''}</div>${g.questions.map((v,qi)=>`<article class="survey-question-editor"><div class="survey-section-head"><h3>문항 ${qi+1}</h3>${B('sur-question-delete','문항삭제','btn danger',`data-group="${gi}" data-question="${qi}"`)}</div>${F('질문',I('q-'+gi+'-'+qi,'text',v.title,'required'))}<div class="survey-question-controls">${F('문항 구분',`<select name="type-${gi}-${qi}" data-survey-type>${O(surveyTypes,v.type)}</select>`)}<label class="check"><input type="checkbox" name="required-${gi}-${qi}" ${v.required?'checked':''}> 필수응답</label></div>${!['단답형','서술형'].includes(v.type)?`<div class="survey-option-edit">${v.options.map((o,oi)=>`<div class="row">${F((oi+1)+')',I('o-'+gi+'-'+qi+'-'+oi,'text',o.label,'required'))}${v.type!=='척도형'?`<label class="check"><input type="checkbox" name="extra-${gi}-${qi}-${oi}" ${o.extra?'checked':''}> 부가정보 입력</label>`:''}${oi?B('sur-option-delete','보기삭제','btn ghost',`data-group="${gi}" data-question="${qi}" data-option="${oi}"`):''}</div>`).join('')}${B('sur-option-add','보기추가','btn',`data-group="${gi}" data-question="${qi}"`)}</div>`:''}</article>`).join('')}${B('sur-question-add','문항추가','btn',`data-group="${gi}"`)}</div></details>`).join('')}</section></fieldset><div class="survey-editor-footer">${B('sur-manage-back','취소')}${B('sur-editor-preview','미리보기')}${locked?B('sur-copy','복사하여 등록','btn primary',`data-id="${E(q.id)}"`):'<button type="submit" class="btn primary">저장</button>'}</div></form>`}
function surveyReadEditor(){const q=surveyUi.editor,f=document.getElementById('survey-editor');if(!f||q.responses.length)return;const fd=new FormData(f);for(const k of ['title','intro','outro','start','end','target'])q[k]=String(fd.get(k)||'');q.year=Number(fd.get('year'));q.minutes=Number(fd.get('minutes'));q.audience=Number(fd.get('audience'));q.active=fd.get('active')==='true';q.groups.forEach((g,gi)=>{g.title=String(fd.get('g-'+gi)||'');g.questions.forEach((v,qi)=>{v.title=String(fd.get(`q-${gi}-${qi}`)||'');v.required=fd.has(`required-${gi}-${qi}`);v.options.forEach((o,oi)=>{if(fd.has(`o-${gi}-${qi}-${oi}`))o.label=String(fd.get(`o-${gi}-${qi}-${oi}`)||'');o.extra=fd.has(`extra-${gi}-${qi}-${oi}`)})})})}
function surveyPaper(q,response=null){let number=0;return `<div class="survey-paper"><h2>${E(q.title)}</h2><p class="survey-intro">${E(q.intro)}</p><dl class="detaildata"><dt>대상</dt><dd>${E(q.target)}</dd><dt>예상 소요시간</dt><dd>${q.minutes}분</dd><dt>응답자</dt><dd>${response?E(response.name+' ('+response.userId+')'):'응답자 정보 자동 표시'}</dd>${q.target==='해외 바이어'?`<dt>지원 통역원</dt><dd>${response?E(response.helper||'지원 없음'):'응답 지원 시 통역원 기록'}</dd>`:''}</dl>${q.groups.map((g,gi)=>`<section class="survey-paper-group"><h3>${E(g.title)}</h3>${g.questions.map((v,qi)=>{const key=gi+'-'+qi,a=response?.answers[key],values=Array.isArray(a)?a:[a];return `<div class="survey-paper-question"><strong>${++number}. ${E(v.title)} ${v.required?'<small>필수</small>':''}</strong>${['단답형','서술형'].includes(v.type)?v.type==='단답형'?`<input type="text" value="${E(a||'')}" disabled>`:`<textarea disabled>${E(a||'')}</textarea>`:`<div class="survey-answer-options ${v.type==='척도형'?'scale':''}">${v.options.map((o,oi)=>`<label><input type="${v.type==='복수응답형'?'checkbox':'radio'}" name="paper-${key}" disabled ${values.includes(String(oi))?'checked':''}><span>${v.type==='척도형'?(oi+1)+'. ':''}${E(o.label)}</span>${o.extra&&values.includes(String(oi))?`<span>${E(response?.extras?.[key+'-'+oi]||'')}</span>`:''}</label>`).join('')}</div>`}</div>`}).join('')}</section>`).join('')}<p class="survey-outro">${E(q.outro)}</p>${!response?'<p class="small">미리보기에서는 응답 입력·제출을 할 수 없습니다.</p>':''}</div>`}
function surveyResponseList(s){const rr=surveyListed(true);return `${head({...s,title:'응답관리',summary:'연도별·대상별 설문 응답을 조회하고 통계와 개별 응답을 확인한다.'})}${surveyListFilter(true)}<section class="panel"><div class="panelhead"><h2>설문 응답 목록</h2><span>${rr.length}건 · 응답</span></div><div class="tablewrap"><table><thead><tr><th>연도</th><th>대상</th><th>설문제목</th><th>조사 대상수</th><th>응답수</th><th>응답률</th><th>최근 응답일시</th><th>상세</th></tr></thead><tbody>${rr.map(q=>`<tr><td>${q.year}</td><td>${E(q.target)}</td><td>${B('sur-result',q.title,'btn ghost',`data-id="${E(q.id)}"`)}</td><td>${q.audience}명</td><td>${q.responses.length}건</td><td>${q.audience?(q.responses.length/q.audience*100).toFixed(1):'0.0'}%</td><td>${E(q.responses.map(r=>r.date).sort().at(-1)||'응답 없음')}</td><td>${B('sur-result','통계·이력','btn',`data-id="${E(q.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="8">조회된 응답 설문이 없습니다.</td></tr>'}</tbody></table></div></section>`}
function surveyResponses(q){return q.responses.filter(r=>(!surveyUi.from||r.date.slice(0,10)>=surveyUi.from)&&(!surveyUi.to||r.date.slice(0,10)<=surveyUi.to))}
function surveyStats(q,rr){return q.groups.map((g,gi)=>`<section class="panel pad"><h2>${E(g.title)}</h2>${g.questions.map((v,qi)=>{const key=gi+'-'+qi,answered=rr.filter(r=>r.answers[key]!==undefined&&r.answers[key]!==''),text=['단답형','서술형'].includes(v.type);return `<article class="survey-stats-question"><div class="survey-section-head"><h3>${qi+1}. ${E(v.title)} <small>[${v.type}]</small></h3><span class="small">응답 ${answered.length}건</span></div>${text?B('sur-text-results',v.type+' 응답 '+answered.length+'건 보기','btn',`data-group="${gi}" data-question="${qi}"`):v.options.map((o,oi)=>{const n=answered.filter(r=>{const a=r.answers[key];return (Array.isArray(a)?a:[a]).includes(String(oi))}).length,p=answered.length?n/answered.length*100:0;return `<div class="survey-result-bar"><span>${E(o.label)}</span><div><i style="width:${p}%;background:${annualColors[oi%annualColors.length]}"></i></div><b>${n}명 · ${p.toFixed(1)}%</b></div>`}).join('')}${v.type==='복수응답형'?'<p class="small">복수응답은 응답자 수 기준이며 비율 합계가 100%를 넘을 수 있습니다.</p>':''}</article>`}).join('')}</section>`).join('')}
function surveyHistory(q,rr){const size=surveyUi.historySize,page=surveyUi.historyPage,pages=Math.max(1,Math.ceil(rr.length/size)),shown=[...rr].sort((a,b)=>b.date.localeCompare(a.date)).slice((page-1)*size,page*size);return `<section class="panel"><div class="panelhead"><h2>사용자별 응답 이력</h2>${F('목록 건수',`<select id="survey-history-size">${O(['10','30','50'],String(size))}</select>`)}</div><div class="tablewrap"><table><thead><tr><th>No.</th><th>고유 번호</th><th>응답자</th>${q.target==='해외 바이어'?'<th>지원 통역원</th>':''}<th>응답일시</th><th>결과</th></tr></thead><tbody>${shown.map((r,i)=>`<tr><td>${(page-1)*size+i+1}</td><td>${E(r.userId)}</td><td>${E(r.name)}</td>${q.target==='해외 바이어'?`<td>${E(r.helper||'지원 없음')}</td>`:''}<td>${E(r.date)}</td><td>${B('sur-individual','결과보기','btn',`data-id="${E(r.id)}"`)}</td></tr>`).join('')||`<tr><td colspan="${q.target==='해외 바이어'?6:5}">응답 이력이 없습니다.</td></tr>`}</tbody></table></div><div class="tablefoot"><span>총 <strong>${rr.length}</strong>건 · ${page}/${pages}page</span><div class="row">${B('sur-history-prev','이전','btn',page<=1?'disabled':'')}<span>${page}/${pages}page</span>${B('sur-history-next','다음','btn',page>=pages?'disabled':'')}</div></div></section>`}
function surveyResultPage(s){const q=surveyFind(surveyUi.id);if(!q){surveyUi.response='list';return surveyResponseList(s)}const rr=surveyResponses(q);return `${head({...s,title:q.title+' 응답결과',summary:q.year+'년 · '+q.target},B('sur-response-back','목록으로'))}<div class="notice">${E(q.title)} · ${E(q.target)} · 조회 응답 ${rr.length}건</div><form id="survey-date-filter" class="panel filters">${surveyField('응답 시작일','from',surveyUi.from,'date')}${surveyField('응답 종료일','to',surveyUi.to,'date')}<div class="row"><button type="submit" class="btn primary">검색</button>${B('sur-date-reset','초기화')}</div></form><div class="survey-tabs" role="tablist" aria-label="응답결과">${['stats','history'].map(tab=>`<button type="button" class="btn ${surveyUi.tab===tab?'primary':''}" role="tab" aria-selected="${surveyUi.tab===tab}" data-action="sur-tab" data-tab="${tab}">${tab==='stats'?'통계':'이력'}</button>`).join('')}</div>${surveyUi.tab==='stats'?surveyStats(q,rr):surveyHistory(q,rr)}`}
