function surveyNew(q=null){const year=2026;surveyUi.editor=q?surveyClone(q):{id:'SUR-'+Date.now(),year,target:surveyTargets[0],title:'',minutes:5,intro:'',outro:'',active:true,start:year+'-10-01',end:year+'-12-31',created:new Date().toISOString().slice(0,10),audience:0,groups:[{title:'',questions:[surveyQuestion()]}],responses:[]};surveyUi.manage='editor';modal(q?'설문 수정':'설문 등록',surveyEditor(map.get('SET-05')));const page=window.GFAIR_WORKFLOW?.entry(location.hash.slice(1));if(page)page.build=()=>surveyEditor(map.get('SET-05'))}
function surveyAction(ev){const b=ev.target.closest('[data-action]');if(!b||!b.dataset.action.startsWith('sur-'))return;ev.preventDefault();if(dialog.contains(b))ev.stopImmediatePropagation();const a=b.dataset.action,q=surveyUi.editor,gi=Number(b.dataset.group),qi=Number(b.dataset.question),oi=Number(b.dataset.option);if(a==='sur-use'){const selected=surveyFind(b.dataset.id);selected.active=!selected.active;surveyPersist();render()}else if(a==='sur-create')surveyNew();else if(a==='sur-edit')surveyNew(surveyFind(b.dataset.id));else if(a==='sur-manage-back'){surveyUi.manage='list';if(window.GFAIR_WORKFLOW?.entry(location.hash.slice(1)))window.GFAIR_WORKFLOW.back();else render()}else if(a==='sur-response-back'){surveyUi.response='list';nav('SET-06')}else if(a==='sur-preview')modal('설문 미리보기',surveyPaper(surveyFind(b.dataset.id)),'close','닫기','SET-13');else if(a==='sur-editor-preview'){surveyReadEditor();modal('설문 미리보기',surveyPaper(q),'close','닫기','SET-13')}else if(a==='sur-copy'){const source=surveyFind(b.dataset.id),copy=surveyClone(source),baseTitle=source.title.replace(/ – 복사본(?:\(\d+\))?$/,'');let n=1;while(surveyStore.some(s=>s.title===baseTitle+' – 복사본'+(n===1?'':'('+n+')')))n++;copy.id='SUR-'+Date.now();copy.title=baseTitle+' – 복사본'+(n===1?'':'('+n+')');copy.responses=[];copy.created=new Date().toISOString().slice(0,10);surveyStore.push(copy);surveyPersist();surveyUi.manage='list';render();toast('설문을 복사했습니다.')}else if(a==='sur-delete'){modal('설문 삭제',`<p>${E(surveyFind(b.dataset.id).title)}을 삭제할까요?</p><p class="small">해당 설문의 응답도 함께 삭제됩니다.</p><button type="button" class="btn danger" data-action="sur-delete-confirm" data-id="${E(b.dataset.id)}">삭제 확인</button>`)}else if(a==='sur-delete-confirm'){surveyStore=surveyStore.filter(q=>q.id!==b.dataset.id);surveyPersist();dialog.close();render()}else if(['sur-group-add','sur-group-delete','sur-question-add','sur-question-delete','sur-option-add','sur-option-delete'].includes(a)){if(q.responses.length)return;surveyReadEditor();if(a==='sur-group-add')q.groups.push({title:'',questions:[surveyQuestion()]});if(a==='sur-group-delete'&&gi>0)q.groups.splice(gi,1);if(a==='sur-question-add')q.groups[gi].questions.push(surveyQuestion());if(a==='sur-question-delete'){if(q.groups[gi].questions.length===1)return toast('그룹에는 최소 한 문항이 필요합니다.');q.groups[gi].questions.splice(qi,1)}if(a==='sur-option-add')q.groups[gi].questions[qi].options.push({label:'',extra:false});if(a==='sur-option-delete'&&oi>0)q.groups[gi].questions[qi].options.splice(oi,1);render()}else if(a==='sur-result'){const selected=surveyFind(b.dataset.id);surveyUi.id=selected.id;surveyUi.response='detail';surveyUi.tab='stats';surveyUi.from=selected.year+'-01-01';surveyUi.to=selected.year+'-12-31';surveyUi.historyPage=1;nav('SET-16')}else if(a==='sur-tab'){surveyUi.tab=b.dataset.tab;render()}else if(a==='sur-individual'){const selected=surveyFind(surveyUi.id),r=selected.responses.find(r=>r.id===b.dataset.id);modal('개별 설문 응답',surveyPaper(selected,r))}else if(a==='sur-text-results'){const selected=surveyFind(surveyUi.id),key=gi+'-'+qi,rr=surveyResponses(selected).filter(r=>r.answers[key]);modal('주관식 응답',`<h3>${E(selected.groups[gi].questions[qi].title)}</h3><div class="tablewrap"><table><thead><tr><th>응답자</th><th>응답일시</th><th>내용</th></tr></thead><tbody>${rr.map(r=>`<tr><td>${E(r.name)}</td><td>${E(r.date)}</td><td>${E(r.answers[key])}</td></tr>`).join('')||'<tr><td colspan="3">응답이 없습니다.</td></tr>'}</tbody></table></div>`)}else if(a==='sur-history-prev'){surveyUi.historyPage--;render()}else if(a==='sur-history-next'){surveyUi.historyPage++;render()}else if(a==='sur-manage-reset'){Object.assign(surveyUi.filters,{year:'전체',target:'전체',active:'전체',query:''});render()}else if(a==='sur-response-reset'){Object.assign(surveyUi.responseFilters,{year:'2026',target:'전체',query:''});render()}else if(a==='sur-date-reset'){const selected=surveyFind(surveyUi.id);surveyUi.from=selected.year+'-01-01';surveyUi.to=selected.year+'-12-31';surveyUi.historyPage=1;render()}}
root.addEventListener('click',surveyAction);document.getElementById('dialog-content').addEventListener('click',surveyAction,true);
root.addEventListener('change',ev=>{if(ev.target.matches('[data-survey-type]')){surveyReadEditor();const [,g,q]=ev.target.name.split('-').map(Number),question=surveyUi.editor.groups[g].questions[q];question.type=ev.target.value;if(question.type==='척도형')question.options=surveyQuestion('척도형').options;render()}if(ev.target.id==='survey-history-size'){surveyUi.historySize=Number(ev.target.value);surveyUi.historyPage=1;render()}});
