 root.querySelectorAll('#content table').forEach(table=>{const indexes=[...table.querySelectorAll('thead tr:last-child>th')].map((th,i)=>/고유\s*(번호|코드)|행사\s*이력/.test(th.textContent)?i:-1).filter(i=>i>=0);for(const row of table.rows)indexes.forEach(i=>{if(row.cells[i])row.cells[i].hidden=true;});});
