function openPreMatching(){
 const rr=rows(map.get('PRE-04')),record=rr[selectedRow]||rr[0];if(!record)return toast('매칭할 해외 바이어가 없습니다.');
 const options=rows(map.get('BAS-07')).map(r=>({name:r[1],language:r[3]}));
 const d=document.getElementById('dialog');d.dataset.screenId='PRE-05';
 document.getElementById('dialog-content').innerHTML=`<div class="dialoghead"><h2>통역원 매칭 처리</h2><button type="button" class="btn ghost" data-prematch-close aria-label="닫기">×</button></div><div class="dialogbody"><form id="prematch-form"><div class="formgrid">${F('해외 바이어','<p>'+E(record[0])+'</p>')}${F('현재 통역원','<p>'+E(record[2])+'</p>')}${F('통역원 선택','<select name="interpreter" required><option value="">선택하세요</option>'+options.map(o=>'<option value="'+E(o.name)+'"'+(o.name===record[2]?' selected':'')+'>'+E(o.name+' · '+o.language)+'</option>').join('')+'</select>')}</div><div class="formfooter"><button type="button" class="btn" data-prematch-cancel ${record[2]==='미지정'?'disabled':''}>매칭 취소</button><button type="button" class="btn" data-prematch-close>닫기</button><button type="submit" class="btn primary">${record[2]==='미지정'?'매칭':'매칭 변경'}</button></div></form></div>`;
 d.showModal();
}
document.addEventListener('click',e=>{if(!e.target.closest('[data-prematch-close],[data-prematch-cancel]'))return;e.preventDefault();e.stopImmediatePropagation();const d=document.getElementById('dialog');if(e.target.closest('[data-prematch-cancel]')){const rr=rows(map.get('PRE-04')),r=rr[selectedRow]||rr[0];r[2]='미지정';r[3]='언어 미등록';r[5]='미매칭';lists['PRE-04']=rr;d.close();render();toast('통역원 매칭을 취소했습니다.');}else d.close();},true);
